-- What players read for each series (the series keys stay internal).
Fighters.SeriesNames = {
	["AOT"] = "Titan Wall",
	["Bleach"] = "Soul Blades",
	["DBZ"] = "Dragon Fighters",
	["Demon Slayer"] = "Demon Hunters",
	["FATE"] = "Grail War",
	["Fairy Tail"] = "Fairy Guild",
	["HXH"] = "Hunter Exam",
	["JJK"] = "Cursed School",
	["JOJO"] = "Bizarre Stands",
	["My Hero Academia"] = "Hero Academy",
	["NARUTO"] = "Hidden Leaf",
	["OTHER"] = "Wild Cards",
	["One Piece"] = "Grand Pirates",
	["YYH"] = "Spirit Detectives",
}
-- ByKey: every fighter (old saves). Launch: the launch roster, in list order. ByRarity: what summons,
-- the Secret Rush and gifts draw from (launch, no boss exclusives). ByPool[pool][rarity]: what each
-- zone's altars drop (Hub, Blossom, Ninja, Pirate, Walled; the Divine pool is never dropped).
Fighters.ByKey = {}
Fighters.Launch = {}
Fighters.ByRarity = {}
Fighters.ByPool = {}
for _, fighter in Fighters.List do
	Fighters.ByKey[fighter.key] = fighter
	if fighter.launch then
		table.insert(Fighters.Launch, fighter)
		if not fighter.exclusive then
			Fighters.ByRarity[fighter.rarity] = Fighters.ByRarity[fighter.rarity] or {}
			table.insert(Fighters.ByRarity[fighter.rarity], fighter)
			local pool = Fighters.ByPool[fighter.pool] or {}
			Fighters.ByPool[fighter.pool] = pool
			pool[fighter.rarity] = pool[fighter.rarity] or {}
			table.insert(pool[fighter.rarity], fighter)
		end
	end
end
-- Signature poses (clips Sig* in shared/Clips.lua, authored in tools/blender/r15_studio.py): each series'
-- iconic stance, played when a fighter lands, wins, goes on a stand or is revealed. A few characters have
-- their own.
local SIGNATURE_BY_SERIES = {
	JJK = "SigGojo",
	JOJO = "SigJojo",
	DBZ = "SigKamehameha",
	NARUTO = "SigSeal",
	["One Piece"] = "SigLaugh",
	["My Hero Academia"] = "SigSmash",
	AOT = "SigSalute",
	Bleach = "SigBankai",
	HXH = "SigJajanken",
	FATE = "SigSword",
	YYH = "SigSpiritGun",
	["Fairy Tail"] = "SigGuild",
}
local SIGNATURE_BY_KEY = {
	Sukuna = "SigSukuna",
	AllMight = "SigAllMight",
	AllMightMode = "SigAllMight",
	Cell = "SigFlex",
	Mahoraga = "SigFlex",
	GoldenFrieza = "SigFlex",
}

function Fighters.signature(key)
	local fighter = Fighters.ByKey[key]
	return SIGNATURE_BY_KEY[key] or (fighter and SIGNATURE_BY_SERIES[fighter.series]) or "SigFlex"
end

return Fighters
